const body = $('Webhook').item.json.body;
const brandItem = $('Lookup Brand Profile').all()[0];
const brand = brandItem ? brandItem.json : {};

const brandName = brand.brand_name || body.branch || 'the brand';
const tone = body.tone || brand.default_tone || 'friendly';
const pron = brand.pronunciation_guide || '';
const pipeline = body.pipeline || 'talking_head';

// Duration: Kling accepts 5 or 10 only.
const dur = $('Validate Video Request').item.json.duration;

// Script length must FIT the clip. ~2.2 wps, and leave ~1s of head/tail room.
const maxWords = Math.max(6, Math.floor((dur - 1) * 2.2));

const aspect = body.aspect_ratio || '9:16';
const gender = body.actor_gender || 'female';
const style = body.actor_style || 'professional';
const setting = body.setting || brand.default_setting || 'a clean, modern, well-lit interior';

const hook = body.platform === 'tiktok'
  ? 'Write a HOOK-FIRST viral vertical video script that grabs attention in the first 2 seconds. Punchy, conversational, fast-paced.'
  : 'Write a performance-marketing video ad script.';

const script_prompt = `${hook} Brand: ${brandName}. Product: ${body.product_description || ''}. Audience: ${body.target_segment || 'general audience'}. Tone: ${tone}. Call to action: ${body.cta || 'Learn more'}. Pronunciation and brand rules: ${pron}. Write ONLY the spoken words - no stage directions, no parentheticals like (smiling), no narrator labels. Maximum ${maxWords} words. Conversational, natural.`;

// ---- FIRST-FRAME IMAGE PROMPT ----
// This describes a STILL PHOTOGRAPH. No motion, no speech, no narrative.
const frameBase = pipeline === 'full_scene'
  ? `A single still photograph. Vertical ${aspect} composition. Product-forward marketing photograph for ${brandName}. Setting: ${setting}. Subject and offer: ${String(body.product_description || '').slice(0, 1500)}. The product is the clear focal point, positioned in the centre third of the frame.`
  : `A single still photograph. Vertical ${aspect} composition. Medium-close portrait of one ${style} ${gender} person, alone in frame, already standing in place and facing the camera directly. Setting: ${setting}. Mouth closed, neutral-warm expression, eyes to camera. Head and shoulders occupy the centre of the frame with clear headroom above.`;

const frameStyle = `Photorealistic. Natural professional lighting, soft key from camera left. Shallow depth of field. Realistic skin texture and film grain. Colour palette consistent with ${brandName}. No text, no logos, no watermarks, no captions, no borders, no collage, no split screen. Only one person in frame. Sharp focus, correct anatomy, natural hands.`;

const frame_prompt = `${frameBase} ${frameStyle}`;

return [{ json: {
  script: body.script,
  frame_prompt,
  brand_name: brandName,
  duration: String(dur),
  pipeline,
  aspect_ratio: aspect,
  setting,
  actor_gender: gender,
  actor_style: style,
  job_id: body.job_id,
  branch: body.branch,
  is_regenerate: body.regenerate === true,
} }];

// Nano Banana returns content parts; the image arrives as inlineData base64.
const cands = $json.candidates || [];
let b64 = null;
let mime = 'image/png';

for (const c of cands) {
  const parts = (c.content && c.content.parts) || [];
  for (const p of parts) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) {
      b64 = inline.data;
      mime = inline.mimeType || inline.mime_type || mime;
      break;
    }
  }
  if (b64) break;
}

if (!b64) {
  throw new Error('No image returned by Gemini. Raw: ' + JSON.stringify($json).slice(0, 400));
}

const jobId = $('Prepare Prompt').item.json.job_id;
const attempt = Number($('Read Job').item.json.frame_attempt || 0) + 1;
const ext = mime.includes('jpeg') ? 'jpg' : 'png';
// upsert:false + randomised suffix -> avoids UPDATE RLS policy on Storage
const rand = Math.random().toString(36).slice(2, 8);
const path = `video-ad-frames/${jobId}/frame-${attempt}-${rand}.${ext}`;

return [{
  json: { storage_path: path, mime, attempt },
  binary: {
    data: {
      data: b64,
      mimeType: mime,
      fileName: `frame-${attempt}-${rand}.${ext}`,
    },
  },
}];

const body = $('Webhook').item.json.body || {};
if (!/^[0-9a-f-]{36}$/i.test(body.job_id || '') || !body.branch) throw new Error('A job ID and brand are required.');
const script = typeof body.script === 'string' ? body.script : '';
if (!script.trim()) throw new Error('An edited script is required. No replacement script will be generated.');
const requested = Number(body.video_duration || 10);
// Legacy app versions sent 15/30; normalize those explicitly to 10 for compatibility.
const duration = requested === 5 ? 5 : 10;
const maxWords = Math.floor((duration - 1) * 2.2);
if (script.trim().split(/\s+/u).length > maxWords) throw new Error('Shorten the script to ' + maxWords + ' words for this ' + duration + '-second clip. Your words will not be truncated.');
return [{json:{...body, duration, script}}];
